// effectiveMonth 返回新安排的生效账期：请求被接受时的下一月。
// 若请求时刻恰为月初零点（账期边界），则从再下一月生效——
// 此时当月已按新套餐（或原套餐）执行，新安排无法覆盖当月。
func effectiveMonth(now time.Time) Month {
	m := MonthOf(now)
	if now.Equal(m.Start()) {
		return m.AddDate(0, 2, 0)
	}
	return m.AddDate(0, 1, 0)
}

