		t.Fatal(err)
	}
	clk.t = utc(2026, 2, 8, 0, 0)
	st, _ := s.Status("a")
	if !st.Suspended {
		t.Fatal("should be suspended")
	}

	// 停用期间安排切换：成功。
	if _, err := s.SchedulePlanSwitch("a", "B"); err != nil {
		t.Fatalf("schedule while suspended: %v", err)
