	// 停用状态未被清除。
	st, _ = s.Status("a")
	if !st.Suspended {
		t.Fatal("suspension cleared by switch operation")
	}

	// 结清后恢复。
	if _, err := s.RecordPayment("a", "p1", jan(2026), 1000); err != nil {
