	if err != nil {
		t.Fatal(err)
	}
	// 再次选择同一目标套餐：返回原安排，不重新取价。
	sw2, err := s.SchedulePlanSwitch("a", "B")
	if err != nil {
		t.Fatal(err)
	}
	if sw1 != sw2 {
