func TestHistoricalBillingUsesCorrectTerms(t *testing.T) {
	// 连续多次换套餐后，每张账单使用对应账期的完整条件。
	s, clk := switchSetup(t, utc(2026, 1, 1, 0, 0), Plan{
		ID: "A", MonthlyFee: 100, IncludedUnits: 10, OveragePrice: 5, TaxRateBasisPoints: 1000,
	})
